SourceCode.Declaration:
/// <summary>
/// Controller class for fetching inbound messages
/// </summary>
[SysOperationJournaledParametersAttribute(true)]
class OMGInboundMessageFetchController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Constructs the class
/// </summary>
/// <returns>The instantiated OMGInboundMessageFetchController class</returns>
public static OMGInboundMessageFetchController construct()
{
    SysOperationController controller;

    controller = new OMGInboundMessageFetchController();

    return controller;
}

/// <summary>
/// Instantiates the class
/// </summary>
protected void new()
{
    super(classStr(OMGInboundMessageFetchService), methodStr(OMGInboundMessageFetchService, processOperation), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Public handle for the class. Instantiates it, and kicks off processing
/// </summary>
/// <param name = "_args">Args from the caller</param>
public static void main(Args _args)
{
    OMGInboundMessageFetchController controller = OMGInboundMessageFetchController::construct();
    controller.startOperation();

}

/// <summary>
/// The class caption
/// </summary>
/// <returns>The caption</returns>
protected ClassDescription defaultCaption()
{
    return "@OMG:FetchInboundMessages";
}
